var wbm = GameState.state.units["U_WARBOSS_B"].models[0]
var u = GameState.state.units["U_WITCHSEEKERS_C"]
var i = 0
for m in u.models:
	m.position = {"x": float(wbm.position.x) - 500.0, "y": float(wbm.position.y) + i * 30.0}
	i += 1
var best = 9999.0
for m in u.models:
	var d1 = Measurement.model_to_model_distance_inches(m, wbm)
	if d1 < best:
		best = d1
var shift = Measurement.inches_to_px(best - 11.5)
for m in u.models:
	m.position = {"x": float(m.position.x) + shift, "y": float(m.position.y)}
best = 9999.0
for m in u.models:
	var d2 = Measurement.model_to_model_distance_inches(m, wbm)
	if d2 < best:
		best = d2
return snappedf(best, 0.01)

